CREATE TABLE IF NOT EXISTS governance_layers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, scope text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'Planned', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_principles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL UNIQUE, category text NOT NULL, principle text NOT NULL, protected boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
