INSERT INTO governance_layers (name,scope,description) SELECT 'Board of Directors','Group','Ultimate oversight, fiduciary responsibility, strategic supervision and protection of the corporate mandate.' WHERE NOT EXISTS (SELECT 1 FROM governance_layers WHERE name='Board of Directors');
INSERT INTO governance_layers (name,scope,description) SELECT 'Group Executive','Group','Executive management accountable to the Board for strategy and operating performance.' WHERE NOT EXISTS (SELECT 1 FROM governance_layers WHERE name='Group Executive');
INSERT INTO governance_layers (name,scope,description) SELECT 'Regional Leadership','Regional','Coordinates strategy and standards across multiple country operations.' WHERE NOT EXISTS (SELECT 1 FROM governance_layers WHERE name='Regional Leadership');
INSERT INTO governance_layers (name,scope,description) SELECT 'Country Entity','Country','Local legal and operational execution subject to Group standards and applicable law.' WHERE NOT EXISTS (SELECT 1 FROM governance_layers WHERE name='Country Entity');
INSERT INTO governance_layers (name,scope,description) SELECT 'Subsidiary / SPV','Entity','Ring-fenced operating, asset, project or investment vehicle with defined mandate.' WHERE NOT EXISTS (SELECT 1 FROM governance_layers WHERE name='Subsidiary / SPV');
INSERT INTO governance_principles (title,category,principle) SELECT 'Indigenous Ownership & Benefit Protection','Indigenous Rights','No Group structure, asset vehicle, project or transaction may be designed to extinguish legitimate indigenous ownership, customary interests or agreed community benefits.' WHERE NOT EXISTS (SELECT 1 FROM governance_principles WHERE title='Indigenous Ownership & Benefit Protection');
INSERT INTO governance_principles (title,category,principle) SELECT 'Free, Prior & Informed Participation','Community Safeguard','Projects affecting indigenous or host communities require meaningful consultation and documented participation consistent with applicable law and recognised good practice.' WHERE NOT EXISTS (SELECT 1 FROM governance_principles WHERE title='Free, Prior & Informed Participation');
INSERT INTO governance_principles (title,category,principle) SELECT 'Ring-Fenced Entity Integrity','Corporate Governance','Each subsidiary or SPV must have a defined purpose, ownership record, authority matrix, reporting obligations and asset boundary.' WHERE NOT EXISTS (SELECT 1 FROM governance_principles WHERE title='Ring-Fenced Entity Integrity');
INSERT INTO governance_principles (title,category,principle) SELECT 'Separation of Powers','Governance','Board oversight, executive management, assurance and community stewardship must retain appropriately independent responsibilities.' WHERE NOT EXISTS (SELECT 1 FROM governance_principles WHERE title='Separation of Powers');
INSERT INTO governance_principles (title,category,principle) SELECT 'Continental Scalability','Institutional Design','The Group architecture must support new countries, regions, subsidiaries, SPVs and regulated activities without weakening core governance standards.' WHERE NOT EXISTS (SELECT 1 FROM governance_principles WHERE title='Continental Scalability');